const raw = $('DB | Load Salesforce Sync Context').item.json.sync_context;
const ctx = typeof raw === 'string' ? JSON.parse(raw) : raw;
if (!ctx || ctx.connector_key !== 'salesforce_primary') throw new Error('SALESFORCE_SYNC_CONTEXT_INVALID');
let gate = ctx.reliability_gate;
if (typeof gate === 'string') gate = JSON.parse(gate);
const allowed = gate?.allowed === true;
const iso = v => new Date(v).toISOString();
const fields = ['Id','Name','Amount','StageName','OwnerId','LeadSource','CreatedDate','CloseDate','LastModifiedDate','IsClosed','IsWon'];
const soql = 'SELECT ' + fields.join(',') +
  ' FROM Opportunity WHERE LastModifiedDate >= ' + iso(ctx.query_start_at) +
  ' AND LastModifiedDate <= ' + iso(ctx.query_end_at) +
  ' ORDER BY LastModifiedDate ASC';
return {sync_context:ctx,should_sync:allowed,skip_reason:allowed?null:'RELIABILITY_CIRCUIT_OPEN',soql};

const raw = $('DB | Load Salesforce Sync Context').first().json.sync_context;
const ctx = typeof raw === 'string' ? JSON.parse(raw) : raw;
const results = $input.all().map(item => item.json ?? {});
if (results.length > 10000) throw new Error('SALESFORCE_SYNC_RESULT_LIMIT_EXCEEDED');

const expectedCurrency = String(ctx.currency_code ?? 'USD').trim().toUpperCase();
const records = [];
let rejectedCount = 0;
let earliestRejectedAt = null;
const parseDate = value => {
  if (value === null || value === undefined || value === '') return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
};
const asBool = value => value === true || String(value).toLowerCase() === 'true';

for (const r of results) {
  const id = String(r.Id ?? '').trim();
  const amount = Number(r.Amount);
  const stage = String(r.StageName ?? '').trim();
  const updatedAt = parseDate(r.LastModifiedDate);
  const createdAt = parseDate(r.CreatedDate);
  const closeDate = parseDate(r.CloseDate);
  const isWon = asBool(r.IsWon);
  const isClosed = asBool(r.IsClosed);
  const category = isWon ? 'won' : (isClosed ? 'lost' : 'open');
  const currency = String(r.CurrencyIsoCode ?? expectedCurrency).trim().toUpperCase();
  const valid = id.length > 0 && id.length <= 200 &&
    Number.isFinite(amount) && amount >= 0 &&
    /^[A-Z]{3}$/.test(currency) && currency === expectedCurrency &&
    stage.length > 0 && updatedAt !== null &&
    (category === 'open' || closeDate !== null);

  if (!valid) {
    rejectedCount += 1;
    const candidate = updatedAt ? new Date(updatedAt).getTime() : null;
    if (candidate !== null && (earliestRejectedAt === null || candidate < earliestRejectedAt)) earliestRejectedAt = candidate;
    continue;
  }

  records.push({
    source_record_id:id,
    source_payload:{
      Name:r.Name ?? null,
      Amount:String(amount),
      CurrencyIsoCode:currency,
      StageName:stage,
      OwnerId:r.OwnerId ?? null,
      LeadSource:r.LeadSource ?? null,
      CreatedDate:createdAt,
      CloseDate:closeDate,
      LastModifiedDate:updatedAt,
      revint_stage_category:category,
      revint_closed_at:category === 'open' ? null : closeDate
    }
  });
}

const queryStart = new Date(ctx.query_start_at).getTime();
const queryEnd = new Date(ctx.query_end_at).getTime();
let watermarkMs = queryEnd;
if (rejectedCount > 0) watermarkMs = earliestRejectedAt === null ? queryStart : Math.max(queryStart, earliestRejectedAt);

return [{json:{
  connector_key:'salesforce_primary',
  query_start_at:new Date(queryStart).toISOString(),
  query_end_at:new Date(queryEnd).toISOString(),
  watermark:new Date(watermarkMs).toISOString(),
  source_count:results.length,
  record_count:records.length,
  rejected_count:rejectedCount,
  records,
  event_id:'SALESFORCE-SYNC-' + String(queryEnd)
}}];
